        u_xlat0.xy = u_xlat0.xy * vec2(_amount);
        u_xlati24.x = _samples + int(0xFFFFFFFFu);
        u_xlat24.x = float(u_xlati24.x);
        u_xlat1 = u_xlat4;
        for(int u_xlati_loop_1 = 1 ; u_xlati_loop_1<_samples ; u_xlati_loop_1++)
        {
            u_xlat38 = float(u_xlati_loop_1);
            u_xlat38 = u_xlat38 / u_xlat24.x;
            u_xlat3.xy = u_xlat0.xy * vec2(u_xlat38) + u_xlat2.xy;
            u_xlat3 = texture(inputImg, u_xlat3.xy);
            u_xlat5.z = u_xlat38 * 3.0 + -1.5;
            u_xlat5.y = -abs(u_xlat5.z) + 1.0;
            u_xlat5.x = (-u_xlat5.z);
            u_xlat5.xyz = u_xlat5.xyz;
            u_xlat5.xyz = clamp(u_xlat5.xyz, 0.0, 1.0);
            u_xlat5.xyz = u_xlat3.xyz * u_xlat5.xyz;
            u_xlat5.xyz = u_xlat5.xyz * vec3(3.0, 3.0, 3.0) + (-u_xlat3.xyz);
            u_xlat3.xyz = vec3(_dispersion) * u_xlat5.xyz + u_xlat3.xyz;
            u_xlat1 = u_xlat1 + u_xlat3;
            u_xlat1.xyz = u_xlat4.xyz * vec3(vec3(_stay, _stay, _stay)) + u_xlat1.xyz;
        }
        u_xlat0.x = float(_samples);
        u_xlat4 = u_xlat1 / u_xlat0.xxxx;
    }
    fragColor = u_xlat26.xxxx * u_xlat4;
    return;
}
